git checkout -q -b fix/issue-12-double-discount && cat > src/cart.js <<'EOF'
const BULK_MIN_LINES = 10;
const BULK_DISCOUNT = 0.05;

// Cart total in cents. `discount` is the customer's discount rate (0.1 = 10%).
// Carts with 10 or more lines get an extra 5% bulk discount, applied once
// after the customer discount.
export function total(items, discount = 0) {
  const subtotal = items.reduce((sum, item) => sum + item.price * item.qty, 0);
  const bulk = items.length >= BULK_MIN_LINES ? BULK_DISCOUNT : 0;
  return Math.round(subtotal * (1 - discount) * (1 - bulk));
}

export function itemCount(items) {
  return items.reduce((n, item) => n + item.qty, 0);
}
EOF
cat > tests/cart.test.js <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

const lines = (n, price) => Array.from({ length: n }, () => ({ price, qty: 1 }));

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 250);
});

test('customer discount is applied once', () => {
  assert.equal(total([{ price: 500, qty: 2 }], 0.1), 900);
  assert.equal(total(lines(9, 1000), 0.1), 8100);
});

test('bulk discount is applied once, after the customer discount', () => {
  assert.equal(total(lines(10, 1000), 0.1), 8550);
});

test('bulk discount without customer discount', () => {
  assert.equal(total(lines(10, 1000)), 9500);
  assert.equal(total(lines(10, 1000), 0), 9500);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});
EOF
